pub struct Database {
    pub schema: Schema,
    pub tables: Seq<Relation>,
}

#[derive(Clone, Copy)]
pub enum IntKind {
    Int4,
    Int8,
}

pub open spec fn int_in_range(k: IntKind, v: int) -> bool {
    match k {
        IntKind::Int4 => int4_min() <= v <= int4_max(),
        IntKind::Int8 => int8_min() <= v <= int8_max(),
    }
}

pub open spec fn int_result(k: IntKind, v: int) -> Result<Val, SqlError> {
    if int_in_range(k, v) { Ok(Val::Int(v)) } else { Err(SqlError::NumericValueOutOfRange) }
}

pub open spec fn num_in_range(coeff: int, scale: nat) -> bool {
    decimal_digits(abs(coeff)) <= numeric_int_digits_max() + scale
}

pub open spec fn num_result(coeff: int, scale: nat) -> Result<Val, SqlError> {
    if num_in_range(coeff, scale) {
        Ok(Val::Num { coeff, scale })
    } else {
        Err(SqlError::NumericValueOutOfRange)
    }
}

pub open spec fn num_add_coeff(c1: int, s1: nat, c2: int, s2: nat) -> int {
    let s = max_nat(s1, s2);
    align(c1, s1, s) + align(c2, s2, s)
}

pub open spec fn num_sub_coeff(c1: int, s1: nat, c2: int, s2: nat) -> int {
    let s = max_nat(s1, s2);
    align(c1, s1, s) - align(c2, s2, s)
}

pub open spec fn num_cmp(c1: int, s1: nat, c2: int, s2: nat) -> int {
    sign(num_sub_coeff(c1, s1, c2, s2))
}

pub open spec fn pow10(k: nat) -> int
    decreases k,
{
    if k == 0 { 1 } else { 10 * pow10((k - 1) as nat) }
}

pub open spec fn align(coeff: int, from: nat, to: nat) -> int {
    coeff * pow10((to - from) as nat)
}

pub open spec fn max_nat(a: nat, b: nat) -> nat {
    if a >= b { a } else { b }
}

pub open spec fn abs(x: int) -> int {
    if x >= 0 { x } else { -x }
}

pub open spec fn sign(x: int) -> int {
    if x < 0 { -1 } else if x == 0 { 0 } else { 1 }
}

pub open spec fn decimal_digits(n: int) -> nat
    decreases n,
{
    if n <= 0 { 0 } else { 1 + decimal_digits(n / 10) }
}

pub open spec fn date_from_civil(y: int, m: int, d: int) -> int {
    unix_days_from_civil(y, m, d) - unix_to_postgres_days()
}

pub open spec fn civil_from_date(day: int) -> (int, int, int) {
    civil_from_unix_days(day + unix_to_postgres_days())
}

pub open spec fn date_valid(day: int) -> bool {
    date_min() <= day < date_end()
}

pub open spec fn ts_valid(t: int) -> bool {
    timestamp_min() <= t < timestamp_end()
}

pub open spec fn ts_result(t: int) -> Result<int, SqlError> {
    if ts_valid(t) { Ok(t) } else { Err(SqlError::DatetimeFieldOverflow) }
}

pub open spec fn date_to_ts(day: int) -> Result<int, SqlError> {
    ts_result(day * usecs_per_day())
}

pub open spec fn date_as_usecs(day: int) -> int {
    day * usecs_per_day()
}

pub open spec fn valid_ymd(y: int, m: int, d: int) -> bool {
    1 <= m <= 12 && 1 <= d <= days_in_month(y, m)
}

pub open spec fn is_leap(y: int) -> bool {
    y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
}

pub open spec fn days_in_month(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

pub open spec fn unix_days_from_civil(y: int, m: int, d: int) -> int {
    let y1 = if m <= 2 { y - 1 } else { y };
    let era = y1 / 400;
    let yoe = y1 - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub open spec fn civil_from_unix_days(z: int) -> (int, int, int) {
    let z1 = z + 719468;
    let era = z1 / 146097;
    let doe = z1 - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub open spec fn lex_cmp(a: Seq<u8>, b: Seq<u8>) -> int
    decreases a.len(),
{
    if a.len() == 0 {
        if b.len() == 0 { 0 } else { -1 }
    } else if b.len() == 0 {
        1
    } else if a[0] < b[0] {
        -1
    } else if a[0] > b[0] {
        1
    } else {
        lex_cmp(a.drop_first(), b.drop_first())
    }
}

pub open spec fn chars(b: Seq<u8>) -> Seq<Seq<u8>>
    decreases b.len(),
{
    if b.len() == 0 {
        Seq::empty()
    } else {
        let cs = chars(b.drop_last());
        if is_cont(b.last()) && cs.len() > 0 {
            cs.drop_last().push(cs.last().push(b.last()))
        } else {
            cs.push(seq![b.last()])
        }
    }
}

pub open spec fn is_cont(b: u8) -> bool {
    0x80u8 <= b && b < 0xC0u8
}

pub open spec fn concat(cs: Seq<Seq<u8>>) -> Seq<u8>
    decreases cs.len(),
{
    if cs.len() == 0 { Seq::empty() } else { concat(cs.drop_last()) + cs.last() }
}

#[derive(Clone, Copy)]
pub enum SqlType {
    /// `boolean`
    Bool,
    /// `integer` / `int4`
    Int4,
    /// `bigint` / `int8`
    Int8,
    /// `numeric(precision, scale)` / `decimal(p, s)` with `1 <= precision <= 1000`, `0 <= scale <= precision`.
    Numeric { precision: u32, scale: u32 },
    /// `date`
    Date,
    /// `timestamp` (without time zone)
    Timestamp,
    /// `text`
    Text,
    /// `varchar(max_chars)`
    Varchar { max_chars: u32 },
    /// `char(len)` / `bpchar(len)`; values are stored canonical (trailing U+0020 removed).
    Bpchar { len: u32 },
}

#[derive(Clone, Copy)]
pub struct Column {
    pub ty: SqlType,
    pub nullable: bool,
}

pub open spec fn scalar_ty_of(t: SqlType) -> ScalarTy {
    match t {
        SqlType::Bool => ScalarTy::Bool,
        SqlType::Int4 => ScalarTy::Int4,
        SqlType::Int8 => ScalarTy::Int8,
        SqlType::Numeric { precision, scale } => ScalarTy::Numeric { scale },
        SqlType::Date => ScalarTy::Date,
        SqlType::Timestamp => ScalarTy::Timestamp,
        SqlType::Text => ScalarTy::Text,
        SqlType::Varchar { max_chars } => ScalarTy::Text,
        SqlType::Bpchar { len } => ScalarTy::Text,
    }
}

pub open spec fn col_ty_of(c: Column) -> ColTy {
    ColTy { ty: scalar_ty_of(c.ty), nullable: c.nullable }
}

pub open spec fn sql_type_wf(t: SqlType) -> bool {
    match t {
        SqlType::Numeric { precision, scale } => 1 <= precision <= numeric_max_precision() && scale <= precision,
        SqlType::Varchar { max_chars } => 1 <= max_chars <= char_length_max(),
        SqlType::Bpchar { len } => 1 <= len <= char_length_max(),
        _ => true,
    }
}

pub open spec fn columns_wf(cols: Seq<Column>) -> bool
    decreases cols.len(),
{
    cols.len() == 0 || (sql_type_wf(cols.last().ty) && columns_wf(cols.drop_last()))
}

#[derive(Clone, Copy)]
pub enum ScalarTy {
    Bool,
    Int4,
    Int8,
    /// Upper bound on the display scale; typing keeps it `<= numeric_dscale_max()`, so it fits `u32`.
    Numeric { scale: u32 },
    Date,
    Timestamp,
    /// `text`, `varchar(n)` and canonical `char(n)`: one comparison family (bytes, C collation).
    Text,
}

#[derive(Clone, Copy)]
pub struct ColTy {
    pub ty: ScalarTy,
    pub nullable: bool,
}

pub open spec fn nn(ty: ScalarTy) -> ColTy {
    ColTy { ty, nullable: false }
}

pub open spec fn family(t: ScalarTy) -> int {
    match t {
        ScalarTy::Bool => 0,
        ScalarTy::Int4 => 1,
        ScalarTy::Int8 => 1,
        ScalarTy::Numeric { .. } => 1,
        ScalarTy::Date => 2,
        ScalarTy::Timestamp => 2,
        ScalarTy::Text => 3,
    }
}

pub open spec fn kind_accepts(kind: NumKind, t: ScalarTy) -> bool {
    match (kind, t) {
        (NumKind::Int4, ScalarTy::Int4) => true,
        (NumKind::Int8, ScalarTy::Int8) => true,
        (NumKind::Numeric, ScalarTy::Numeric { .. }) => true,
        _ => false,
    }
}

pub open spec fn scale_of(t: ScalarTy) -> nat {
    match t {
        ScalarTy::Numeric { scale } => scale as nat,
        _ => 0,
    }
}

pub struct TableSchema {
    pub columns: Seq<Column>,
    pub constraints: Seq<Constraint>,
}

pub open spec fn schema_wf(schema: Schema) -> bool {
    tables_wf(schema) && constraints_wf(schema)
}

pub open spec fn tables_wf(schema: Schema) -> bool
    decreases schema.len(),
{
    schema.len() == 0 || (columns_wf(schema.last().columns) && tables_wf(schema.drop_last()))
}

pub open spec fn wf_ordered(schema: Schema, oq: OrderedQuery) -> bool {
    schema_wf(schema) && match type_query(schema, Seq::empty(), oq.body) {
        Some(tys) => keys_in_range(oq.keys, tys.len()),
        None => false,
    }
}

pub open spec fn keys_in_range(keys: Seq<OrderKey>, arity: nat) -> bool
    decreases keys.len(),
{
    keys.len() == 0 || (keys.last().col < arity && keys_in_range(keys.drop_last(), arity))
}

pub open spec fn db_wf(db: Database) -> bool {
    &&& schema_wf(db.schema)
    &&& db.tables.len() == db.schema.len()
    &&& forall|t: int, i: int| 0 <= t < db.tables.len() && 0 <= i < db.tables[t].len()
        ==> row_in_table(#[trigger] db.tables[t][i], db.schema[t])
}

pub open spec fn row_in_table(r: Row, t: TableSchema) -> bool {
    r.len() == t.columns.len() && forall|c: int| 0 <= c < r.len() ==> value_in_column(#[trigger] r[c], t.columns[c])
}

pub open spec fn value_in_column(v: Val, c: Column) -> bool {
    match v {
        Val::Null => c.nullable,
        Val::Bool(_) => c.ty is Bool,
        Val::Int(x) => match c.ty {
            SqlType::Int4 => int_in_range(IntKind::Int4, x),
            SqlType::Int8 => int_in_range(IntKind::Int8, x),
            _ => false,
        },
        Val::Num { coeff, scale } => match c.ty {
            SqlType::Numeric { precision, scale: s } => scale == s as nat && abs(coeff) < pow10(precision as nat),
            _ => false,
        },
        Val::Date(d) => c.ty is Date && date_valid(d),
        Val::Ts(t) => c.ty is Timestamp && ts_valid(t),
        Val::Text(b) => match c.ty {
            SqlType::Text => text_ok(b),
            SqlType::Varchar { max_chars } => text_ok(b) && utf8_chars(b) <= max_chars as nat,
            SqlType::Bpchar { len } => text_ok(b) && utf8_chars(b) <= len as nat && (b.len() == 0 || b.last() != 0x20u8),
            _ => false,
        },
    }
}

pub open spec fn text_ok(b: Seq<u8>) -> bool {
    forall|i: int| 0 <= i < b.len() ==> #[trigger] b[i] != 0u8
}

pub open spec fn utf8_chars(b: Seq<u8>) -> nat
    decreases b.len(),
{
    if b.len() == 0 { 0 } else { utf8_chars(b.drop_last()) + if 0x80u8 <= b.last() < 0xC0u8 { 0nat } else { 1nat } }
}

pub enum Constraint {
    /// `PRIMARY KEY (cols)` (`primary`) or `UNIQUE [NULLS [NOT] DISTINCT] (cols)`.
    Key { cols: Seq<nat>, primary: bool, nulls_distinct: bool },
    /// `FOREIGN KEY (cols) REFERENCES table (ref_cols) [MATCH FULL]` (MATCH SIMPLE when `!match_full`).
    ForeignKey { cols: Seq<nat>, table: nat, ref_cols: Seq<nat>, match_full: bool },
    /// `CHECK (p)`, `p` over the table's row (environment = the row).
    Check(Pred),
}

pub open spec fn constraints_hold(db: Database) -> bool {
    forall|t: int, k: int| 0 <= t < db.schema.len() && t < db.tables.len() && 0 <= k < db.schema[t].constraints.len()
        ==> constraint_holds(db, t, #[trigger] db.schema[t].constraints[k])
}

pub open spec fn constraint_holds(db: Database, t: int, c: Constraint) -> bool {
    match c {
        Constraint::Key { cols, primary, nulls_distinct } => key_holds(db.tables[t], cols, primary, nulls_distinct),
        Constraint::ForeignKey { cols, table, ref_cols, match_full } =>
            table < db.tables.len() && fk_holds(db.tables[t], cols, db.tables[table as int], ref_cols, match_full),
        Constraint::Check(p) => check_holds(db, db.tables[t], p),
    }
}

pub open spec fn constraints_wf(schema: Schema) -> bool {
    tables_constraints_wf(schema, schema)
}

pub open spec fn tables_constraints_wf(schema: Schema, ts: Seq<TableSchema>) -> bool
    decreases ts.len(),
{
    ts.len() == 0 || (table_constraints_wf(schema, ts.last(), ts.last().constraints)
        && primary_keys(ts.last().constraints) <= 1 && tables_constraints_wf(schema, ts.drop_last()))
}

pub open spec fn table_constraints_wf(schema: Schema, t: TableSchema, cs: Seq<Constraint>) -> bool
    decreases cs.len(),
{
    cs.len() == 0 || (constraint_wf(schema, t, cs.last()) && table_constraints_wf(schema, t, cs.drop_last()))
}

pub open spec fn primary_keys(cs: Seq<Constraint>) -> nat
    decreases cs.len(),
{
    if cs.len() == 0 {
        0
    } else {
        primary_keys(cs.drop_last()) + match cs.last() {
            Constraint::Key { primary, .. } => if primary { 1nat } else { 0nat },
            _ => 0nat,
        }
    }
}

pub open spec fn key_holds(rows: Relation, cols: Seq<nat>, primary: bool, nulls_distinct: bool) -> bool {
    &&& primary ==> forall|i: int| 0 <= i < rows.len() ==> !has_null(key_of(#[trigger] rows[i], cols))
    &&& forall|i: int, j: int| 0 <= i < j < rows.len() ==> !key_collides(#[trigger] rows[i], #[trigger] rows[j], cols, nulls_distinct)
}

pub open spec fn key_collides(r: Row, s: Row, cols: Seq<nat>, nulls_distinct: bool) -> bool {
    row_not_distinct(key_of(r, cols), key_of(s, cols)) && !(nulls_distinct && has_null(key_of(r, cols)))
}

pub open spec fn key_of(r: Row, cols: Seq<nat>) -> Row {
    cols.map_values(|c: nat| r[c as int])
}

pub open spec fn has_null(k: Row) -> bool {
    exists|i: int| 0 <= i < k.len() && (#[trigger] k[i]) is Null
}

pub open spec fn all_null(k: Row) -> bool {
    forall|i: int| 0 <= i < k.len() ==> (#[trigger] k[i]) is Null
}

pub open spec fn cols_in_range(cols: Seq<nat>, n: nat) -> bool
    decreases cols.len(),
{
    cols.len() == 0 || (cols.last() < n && cols_in_range(cols.drop_last(), n))
}

pub open spec fn cols_distinct(cols: Seq<nat>) -> bool
    decreases cols.len(),
{
    cols.len() == 0 || (!nat_in(cols.drop_last(), cols.last()) && cols_distinct(cols.drop_last()))
}

pub open spec fn cols_not_null(cols: Seq<nat>, columns: Seq<Column>) -> bool
    decreases cols.len(),
{
    cols.len() == 0 || (cols.last() < columns.len() && !columns[cols.last() as int].nullable
        && cols_not_null(cols.drop_last(), columns))
}

pub open spec fn nat_in(s: Seq<nat>, x: nat) -> bool
    decreases s.len(),
{
    s.len() > 0 && (s.last() == x || nat_in(s.drop_last(), x))
}

pub open spec fn fk_holds(rows: Relation, cols: Seq<nat>, target: Relation, ref_cols: Seq<nat>, match_full: bool) -> bool {
    forall|i: int| 0 <= i < rows.len() ==> fk_row_holds(#[trigger] rows[i], cols, target, ref_cols, match_full)
}

pub open spec fn fk_row_holds(r: Row, cols: Seq<nat>, target: Relation, ref_cols: Seq<nat>, match_full: bool) -> bool {
    let k = key_of(r, cols);
    if has_null(k) {
        !match_full || all_null(k)
    } else {
        exists|j: int| 0 <= j < target.len() && key_matches(k, key_of(#[trigger] target[j], ref_cols))
    }
}

pub open spec fn key_matches(k: Row, m: Row) -> bool {
    k.len() == m.len() && forall|i: int| 0 <= i < k.len() ==> compare(#[trigger] k[i], m[i]) == Some(0int)
}

pub open spec fn has_key_on(cs: Seq<Constraint>, ref_cols: Seq<nat>) -> bool
    decreases cs.len(),
{
    cs.len() > 0 && (match cs.last() {
        Constraint::Key { cols, .. } => cols.len() == ref_cols.len() && cols_subset(cols, ref_cols),
        _ => false,
    } || has_key_on(cs.drop_last(), ref_cols))
}

pub open spec fn cols_subset(a: Seq<nat>, b: Seq<nat>) -> bool
    decreases a.len(),
{
    a.len() == 0 || (nat_in(b, a.last()) && cols_subset(a.drop_last(), b))
}

pub open spec fn fk_types_ok(child: Seq<Column>, cols: Seq<nat>, parent: Seq<Column>, ref_cols: Seq<nat>) -> bool
    decreases cols.len(),
{
    if cols.len() == 0 || ref_cols.len() == 0 {
        true
    } else {
        cols.last() < child.len() && ref_cols.last() < parent.len()
            && fk_col_types_ok(child[cols.last() as int].ty, parent[ref_cols.last() as int].ty)
            && fk_types_ok(child, cols.drop_last(), parent, ref_cols.drop_last())
    }
}

pub open spec fn fk_col_types_ok(c: SqlType, p: SqlType) -> bool {
    match c {
        SqlType::Bool => p is Bool,
        SqlType::Int4 | SqlType::Int8 => p is Int4 || p is Int8 || p is Numeric,
        SqlType::Numeric { .. } => p is Numeric,
        SqlType::Date | SqlType::Timestamp => p is Date || p is Timestamp,
        SqlType::Text | SqlType::Varchar { .. } => p is Text || p is Varchar,
        SqlType::Bpchar { .. } => p is Text || p is Varchar || p is Bpchar,
    }
}

blocks.doc:
Column type pairs (referencing, referenced) of a foreign key whose PostgreSQL equality is exactly
`compare == Some(0)` on this fragment's values:
- int4/int8 -> int4/int8/numeric and numeric -> numeric: exact value equality (numeric -> int4/int8 is
  rejected by PostgreSQL, 42804);
- date/timestamp -> date/timestamp: exact, dates at midnight;
- text/varchar -> text/varchar: bytes; char(n) -> text/varchar/char(m): the referencing value is cast with
  PostgreSQL's rtrim, which is exactly the canonical stored char(n) value, so bytes again;
- bool -> bool.
Refused: every cross-family pair (PostgreSQL 42804) and text/varchar -> char(n), where PostgreSQL compares
blank-insensitively (`'ab '` references `'ab'`), which byte equality would misjudge.

blocks.code:
pub open spec fn check_holds(db: Database, rows: Relation, p: Pred) -> bool {
    forall|i: int| 0 <= i < rows.len() ==> check_row_holds(db, #[trigger] rows[i], p)
}

pub open spec fn check_row_holds(db: Database, r: Row, p: Pred) -> bool {
    match eval_pred(db, r, p) {
        Ok(Truth::False) => false,
        Ok(_) => true,
        Err(_) => false,
    }
}

pub enum Expr {
    /// Position `i` of the environment `ctx ++ row`.
    Col(nat),
    Lit(Literal),
    /// Unary minus at operand type `kind`.
    Neg { kind: NumKind, arg: Box<Expr> },
    /// `a op b`, both operands of type `kind`.
    Arith { op: ArithOp, kind: NumKind, a: Box<Expr>, b: Box<Expr> },
    Cast { cast: CastOp, arg: Box<Expr> },
    /// `timestamp + interval` with PostgreSQL's interval fields (`INTERVAL '1' YEAR` = 12 months).
    AddInterval { arg: Box<Expr>, months: i32, days: i32, micros: i64 },
    /// Leaf scalar function over the argument values (arguments left to right).
    Call { f: ScalarFn, args: Seq<Expr> },
    /// Searched CASE with one branch: `CASE WHEN cond THEN then_e ELSE else_e END` (lazy: only the taken branch
    /// is evaluated).
    If { cond: Box<Pred>, then_e: Box<Expr>, else_e: Box<Expr> },
    /// Scalar subquery (one column); sees the current environment as its context (correlation).
    Subquery(Box<Query>),
}

pub open spec fn eval_expr(db: Database, env: Row, e: Expr) -> Result<Val, SqlError>
    decreases e,
{
    match e {
        Expr::Col(i) => if i < env.len() { Ok(env[i as int]) } else { Err(SqlError::TypeError) },
        Expr::Lit(l) => lit_val(l),
        Expr::Neg { kind, arg } => match eval_expr(db, env, *arg) {
            Err(err) => Err(err),
            Ok(v) => neg(kind, v),
        },
        Expr::Arith { op, kind, a, b } => match eval_expr(db, env, *a) {
            Err(err) => Err(err),
            Ok(va) => match eval_expr(db, env, *b) {
                Err(err) => Err(err),
                Ok(vb) => arith(op, kind, va, vb),
            },
        },
        Expr::Cast { cast: op, arg } => match eval_expr(db, env, *arg) {
            Err(err) => Err(err),
            Ok(v) => cast(op, v),
        },
        Expr::AddInterval { arg, months, days, micros } => match eval_expr(db, env, *arg) {
            Err(err) => Err(err),
            Ok(v) => add_interval(v, months, days, micros),
        },
        Expr::Call { f, args } => match eval_exprs(db, env, args) {
            Err(err) => Err(err),
            Ok(vs) => apply_fn(f, vs),
        },
        Expr::If { cond, then_e, else_e } => match eval_pred(db, env, *cond) {
            Err(err) => Err(err),
            Ok(Truth::True) => eval_expr(db, env, *then_e),
            Ok(_) => eval_expr(db, env, *else_e),
        },
        Expr::Subquery(q) => match eval_query(db, env, *q) {
            Err(err) => Err(err),
            Ok(rows) => subquery_value(rows),
        },
    }
}

pub open spec fn eval_exprs(db: Database, env: Row, es: Seq<Expr>) -> Result<Row, SqlError>
    decreases es, 1nat,
{
    collect(expr_results(db, env, es))
}

pub open spec fn expr_results(db: Database, env: Row, es: Seq<Expr>) -> Seq<Result<Val, SqlError>>
    decreases es, 0nat,
{
    Seq::new(es.len(), |i: int| if 0 <= i < es.len() { eval_expr(db, env, es[i]) } else { Err(SqlError::TypeError) })
}

pub open spec fn type_expr(schema: Schema, env: Seq<ColTy>, e: Expr) -> Option<ColTy>
    decreases e,
{
    match e {
        Expr::Col(i) => if i < env.len() { Some(env[i as int]) } else { None },
        Expr::Lit(l) => type_lit(l),
        Expr::Neg { kind, arg } => match type_expr(schema, env, *arg) {
            Some(t) => if kind_accepts(kind, t.ty) { Some(t) } else { None },
            None => None,
        },
        Expr::Arith { op, kind, a, b } => match (type_expr(schema, env, *a), type_expr(schema, env, *b)) {
            (Some(ta), Some(tb)) => match arith_ty(op, kind, ta.ty, tb.ty) {
                Some(t) => Some(ColTy { ty: t, nullable: ta.nullable || tb.nullable }),
                None => None,
            },
            _ => None,
        },
        Expr::Cast { cast: op, arg } => match type_expr(schema, env, *arg) {
            Some(t) => match cast_ty(op, t.ty) {
                Some(r) => Some(ColTy { ty: r, nullable: t.nullable }),
                None => None,
            },
            None => None,
        },
        Expr::AddInterval { arg, months, days, micros } => match type_expr(schema, env, *arg) {
            Some(t) => if t.ty is Timestamp { Some(t) } else { None },
            None => None,
        },
        Expr::Call { f, args } => match type_exprs(schema, env, args) {
            Some(ts) => type_fn(f, ts),
            None => None,
        },
        Expr::If { cond, then_e, else_e } =>
            if_ty(type_pred(schema, env, *cond), type_expr(schema, env, *then_e), type_expr(schema, env, *else_e)),
        Expr::Subquery(q) => subquery_ty(type_query(schema, env, *q)),
    }
}

pub open spec fn type_exprs(schema: Schema, env: Seq<ColTy>, es: Seq<Expr>) -> Option<Seq<ColTy>>
    decreases es,
{
    if es.len() == 0 {
        Some(Seq::empty())
    } else {
        match (type_exprs(schema, env, es.drop_last()), type_expr(schema, env, es.last())) {
            (Some(ts), Some(t)) => Some(ts.push(t)),
            _ => None,
        }
    }
}

pub enum Literal {
    /// Typed `NULL` (the type the resolver assigned, e.g. `NULL::integer`).
    Null { ty: ScalarTy },
    Bool(bool),
    /// Integer literal of type `kind` (`int4` if it fits, else `int8`; larger literals are numeric).
    Int { v: int, kind: IntKind },
    /// Decimal literal `coeff * 10^-scale` (`0.060` is `{60, 3}`).
    Num { coeff: int, scale: nat },
    /// `DATE 'y-m-d'` (civil components; validity is checked by typing).
    Date { y: int, m: int, d: int },
    /// String literal bytes (UTF-8). For comparison with `char(n)` the resolver right-trims spaces.
    Text(Seq<u8>),
}

pub open spec fn lit_val(l: Literal) -> Result<Val, SqlError> {
    match l {
        Literal::Null { .. } => Ok(Val::Null),
        Literal::Bool(b) => Ok(Val::Bool(b)),
        Literal::Int { v, kind } => if int_in_range(kind, v) { Ok(Val::Int(v)) } else { Err(SqlError::TypeError) },
        Literal::Num { coeff, scale } =>
            if scale <= numeric_dscale_max() && num_in_range(coeff, scale) {
                Ok(Val::Num { coeff, scale })
            } else {
                Err(SqlError::TypeError)
            },
        Literal::Date { y, m, d } =>
            if valid_ymd(y, m, d) && date_valid(date_from_civil(y, m, d)) {
                Ok(Val::Date(date_from_civil(y, m, d)))
            } else {
                Err(SqlError::TypeError)
            },
        Literal::Text(bytes) => Ok(Val::Text(bytes)),
    }
}

pub open spec fn type_lit(l: Literal) -> Option<ColTy> {
    match l {
        Literal::Null { ty } => Some(ColTy { ty, nullable: true }),
        Literal::Bool(_) => Some(nn(ScalarTy::Bool)),
        Literal::Int { v, kind } =>
            if !int_in_range(kind, v) { None } else {
                Some(nn(match kind { IntKind::Int4 => ScalarTy::Int4, IntKind::Int8 => ScalarTy::Int8 }))
            },
        Literal::Num { coeff, scale } =>
            if scale <= numeric_dscale_max() && num_in_range(coeff, scale) {
                Some(nn(ScalarTy::Numeric { scale: scale as u32 }))
            } else {
                None
            },
        Literal::Date { y, m, d } =>
            if valid_ymd(y, m, d) && date_valid(date_from_civil(y, m, d)) { Some(nn(ScalarTy::Date)) } else { None },
        Literal::Text(_) => Some(nn(ScalarTy::Text)),
    }
}

#[derive(Clone, Copy)]
pub enum ArithOp {
    Add,
    Sub,
    Mul,
}

#[derive(Clone, Copy)]
pub enum NumKind {
    Int4,
    Int8,
    Numeric,
}

Expr::Neg { kind, arg } => match eval_expr(db, env, *arg) {
    Err(err) => Err(err),
    Ok(v) => neg(kind, v),
},

Expr::Arith { op, kind, a, b } => match eval_expr(db, env, *a) {
    Err(err) => Err(err),
    Ok(va) => match eval_expr(db, env, *b) {
        Err(err) => Err(err),
        Ok(vb) => arith(op, kind, va, vb),
    },
},

pub open spec fn arith(op: ArithOp, kind: NumKind, a: Val, b: Val) -> Result<Val, SqlError> {
    match (a, b) {
        (Val::Null, Val::Null) => Ok(Val::Null),
        (Val::Null, Val::Int(_)) => Ok(Val::Null),
        (Val::Int(_), Val::Null) => Ok(Val::Null),
        (Val::Null, Val::Num { .. }) => Ok(Val::Null),
        (Val::Num { .. }, Val::Null) => Ok(Val::Null),
        (Val::Int(x), Val::Int(y)) => match kind {
            NumKind::Numeric => Err(SqlError::TypeError),
            _ => int_result(int_kind_of(kind), int_arith(op, x, y)),
        },
        (Val::Num { coeff: c1, scale: s1 }, Val::Num { coeff: c2, scale: s2 }) => match kind {
            NumKind::Numeric => {
                let r = num_arith(op, c1, s1, c2, s2);
                num_result(r.0, r.1)
            },
            _ => Err(SqlError::TypeError),
        },
        _ => Err(SqlError::TypeError),
    }
}

pub open spec fn neg(kind: NumKind, a: Val) -> Result<Val, SqlError> {
    match a {
        Val::Null => Ok(Val::Null),
        Val::Int(x) => match kind {
            NumKind::Numeric => Err(SqlError::TypeError),
            _ => int_result(int_kind_of(kind), -x),
        },
        Val::Num { coeff, scale } => match kind {
            NumKind::Numeric => num_result(-coeff, scale),
            _ => Err(SqlError::TypeError),
        },
        _ => Err(SqlError::TypeError),
    }
}

pub open spec fn int_arith(op: ArithOp, a: int, b: int) -> int {
    match op {
        ArithOp::Add => a + b,
        ArithOp::Sub => a - b,
        ArithOp::Mul => a * b,
    }
}

pub open spec fn num_arith(op: ArithOp, c1: int, s1: nat, c2: int, s2: nat) -> (int, nat) {
    match op {
        ArithOp::Add => (num_add_coeff(c1, s1, c2, s2), max_nat(s1, s2)),
        ArithOp::Sub => (num_sub_coeff(c1, s1, c2, s2), max_nat(s1, s2)),
        ArithOp::Mul => (c1 * c2, s1 + s2),
    }
}

pub open spec fn int_kind_of(k: NumKind) -> IntKind {
    match k {
        NumKind::Int8 => IntKind::Int8,
        _ => IntKind::Int4,
    }
}

Expr::Neg { kind, arg } => match type_expr(schema, env, *arg) {
    Some(t) => if kind_accepts(kind, t.ty) { Some(t) } else { None },
    None => None,
},

Expr::Arith { op, kind, a, b } => match (type_expr(schema, env, *a), type_expr(schema, env, *b)) {
    (Some(ta), Some(tb)) => match arith_ty(op, kind, ta.ty, tb.ty) {
        Some(t) => Some(ColTy { ty: t, nullable: ta.nullable || tb.nullable }),
        None => None,
    },
    _ => None,
},

pub open spec fn arith_ty(op: ArithOp, kind: NumKind, ta: ScalarTy, tb: ScalarTy) -> Option<ScalarTy> {
    if !kind_accepts(kind, ta) || !kind_accepts(kind, tb) {
        None
    } else {
        match kind {
            NumKind::Numeric => {
                let s = match op {
                    ArithOp::Mul => scale_of(ta) + scale_of(tb),
                    _ => max_nat(scale_of(ta), scale_of(tb)),
                };
                if s <= numeric_dscale_max() { Some(ScalarTy::Numeric { scale: s as u32 }) } else { None }
            },
            _ => Some(ta),
        }
    }
}

pub open spec fn apply_div(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    if args.len() != 2 {
        Err(SqlError::TypeError)
    } else {
        match (args[0], args[1]) {
            (Val::Null, _) => Ok(Val::Null),
            (_, Val::Null) => Ok(Val::Null),
            (Val::Int(a), Val::Int(b)) => match f {
                ScalarFn::DivInt4 => int_div(IntKind::Int4, a, b),
                ScalarFn::DivInt8 => int_div(IntKind::Int8, a, b),
                _ => Err(SqlError::TypeError),
            },
            (Val::Num { coeff: c1, scale: s1 }, Val::Num { coeff: c2, scale: s2 }) => match f {
                ScalarFn::DivNumeric => num_div(c1, s1, c2, s2),
                _ => Err(SqlError::TypeError),
            },
            _ => Err(SqlError::TypeError),
        }
    }
}

pub open spec fn int_div(k: IntKind, a: int, b: int) -> Result<Val, SqlError> {
    if b == 0 { Err(SqlError::DivisionByZero) } else { int_result(k, trunc_div(a, b)) }
}

pub open spec fn trunc_div(a: int, b: int) -> int {
    sign(a) * sign(b) * (abs(a) / abs(b))
}

pub open spec fn num_div(c1: int, s1: nat, c2: int, s2: nat) -> Result<Val, SqlError> {
    if c2 == 0 {
        Err(SqlError::DivisionByZero)
    } else {
        num_result(num_div_coeff(c1, s1, c2, s2), div_scale(c1, s1, c2, s2))
    }
}

pub open spec fn num_div_coeff(c1: int, s1: nat, c2: int, s2: nat) -> int {
    let r = div_scale(c1, s1, c2, s2);
    sign(c1) * sign(c2) * div_round(abs(c1) * pow10(r + s2), abs(c2) * pow10(s1))
}

pub open spec fn div_scale(c1: int, s1: nat, c2: int, s2: nat) -> nat {
    let qw0 = nbase_weight(c1, s1) - nbase_weight(c2, s2);
    let qweight = if nbase_first_digit(c1, s1) <= nbase_first_digit(c2, s2) { qw0 - 1 } else { qw0 };
    let r0 = numeric_min_sig_digits() - qweight * dec_digits();
    let r1 = if r0 >= s1 { r0 } else { s1 as int };
    let r2 = if r1 >= s2 { r1 } else { s2 as int };
    let r3 = if r2 >= 0 { r2 } else { 0 };
    let r4 = if r3 <= numeric_max_display_scale() { r3 } else { numeric_max_display_scale() };
    r4 as nat
}

pub open spec fn div_round(n: int, d: int) -> int {
    (2 * n + d) / (2 * d)
}

pub open spec fn nbase_weight(coeff: int, scale: nat) -> int {
    if coeff == 0 { 0 } else { (decimal_digits(abs(coeff)) - 1 - scale) / dec_digits() }
}

pub open spec fn nbase_first_digit(coeff: int, scale: nat) -> int {
    if coeff == 0 {
        0
    } else {
        let t = 0 - scale - dec_digits() * nbase_weight(coeff, scale);
        if t >= 0 { abs(coeff) * pow10(t as nat) } else { abs(coeff) / pow10((0 - t) as nat) }
    }
}

pub open spec fn type_div(f: ScalarFn, args: Seq<ColTy>) -> Option<ColTy> {
    if args.len() != 2 {
        None
    } else {
        let nullable = args[0].nullable || args[1].nullable;
        match (f, args[0].ty, args[1].ty) {
            (ScalarFn::DivInt4, ScalarTy::Int4, ScalarTy::Int4) => Some(ColTy { ty: ScalarTy::Int4, nullable }),
            (ScalarFn::DivInt8, ScalarTy::Int8, ScalarTy::Int8) => Some(ColTy { ty: ScalarTy::Int8, nullable }),
            (ScalarFn::DivNumeric, ScalarTy::Numeric { .. }, ScalarTy::Numeric { .. }) =>
                Some(ColTy { ty: ScalarTy::Numeric { scale: 1000 }, nullable }),
            _ => None,
        }
    }
}

pub open spec fn fits_div(f: ScalarFn, args: Seq<Val>) -> bool {
    args.len() == 2 ==> match (f, args[0], args[1]) {
        (ScalarFn::DivNumeric, Val::Num { coeff: c1, scale: s1 }, Val::Num { coeff: c2, scale: s2 }) =>
            num_div_fits(c1, s1, c2, s2),
        _ => true,
    }
}

pub open spec fn num_div_fits(c1: int, s1: nat, c2: int, s2: nat) -> bool {
    c2 == 0 || c1 == 0 || {
        let k = div_scale(c1, s1, c2, s2) + s2 - s1;
        &&& if k >= 0 { in_u128(abs(c1) * pow10(k as nat)) } else { in_u128(abs(c2) * pow10((0 - k) as nat)) }
        &&& in_i128(num_div_coeff(c1, s1, c2, s2))
    }
}

pub open spec fn in_u128(x: int) -> bool {
    0 <= x <= u128::MAX as int
}

pub open spec fn in_i128(x: int) -> bool {
    i128::MIN as int <= x <= i128::MAX as int
}

#[derive(Clone, Copy)]
pub enum CastOp {
    /// `int4 -> int8` (value unchanged).
    Int4ToInt8,
    /// `int4/int8 -> numeric` (exact, scale 0).
    IntToNumeric,
    /// `date -> timestamp` (midnight; 22008 past the timestamp range).
    DateToTimestamp,
}

Expr::Cast { cast: op, arg } => match eval_expr(db, env, *arg) {
    Err(err) => Err(err),
    Ok(v) => cast(op, v),
},

pub open spec fn cast(op: CastOp, a: Val) -> Result<Val, SqlError> {
    match (op, a) {
        (_, Val::Null) => Ok(Val::Null),
        (CastOp::Int4ToInt8, Val::Int(x)) => Ok(Val::Int(x)),
        (CastOp::IntToNumeric, Val::Int(x)) => Ok(Val::Num { coeff: x, scale: 0 }),
        (CastOp::DateToTimestamp, Val::Date(d)) => match date_to_ts(d) {
            Ok(t) => Ok(Val::Ts(t)),
            Err(e) => Err(e),
        },
        _ => Err(SqlError::TypeError),
    }
}

Expr::Cast { cast: op, arg } => match type_expr(schema, env, *arg) {
    Some(t) => match cast_ty(op, t.ty) {
        Some(r) => Some(ColTy { ty: r, nullable: t.nullable }),
        None => None,
    },
    None => None,
},

pub open spec fn cast_ty(op: CastOp, t: ScalarTy) -> Option<ScalarTy> {
    match (op, t) {
        (CastOp::Int4ToInt8, ScalarTy::Int4) => Some(ScalarTy::Int8),
        (CastOp::IntToNumeric, ScalarTy::Int4) => Some(ScalarTy::Numeric { scale: 0 }),
        (CastOp::IntToNumeric, ScalarTy::Int8) => Some(ScalarTy::Numeric { scale: 0 }),
        (CastOp::DateToTimestamp, ScalarTy::Date) => Some(ScalarTy::Timestamp),
        _ => None,
    }
}

Expr::If { cond, then_e, else_e } => match eval_pred(db, env, *cond) {
    Err(err) => Err(err),
    Ok(Truth::True) => eval_expr(db, env, *then_e),
    Ok(_) => eval_expr(db, env, *else_e),
},

pub open spec fn if_ty(cond_ok: bool, then_t: Option<ColTy>, else_t: Option<ColTy>) -> Option<ColTy> {
    match (then_t, else_t) {
        (Some(a), Some(b)) =>
            if cond_ok && same_shape(a.ty, b.ty) {
                Some(ColTy {
                    ty: match (a.ty, b.ty) {
                        (ScalarTy::Numeric { scale: x }, ScalarTy::Numeric { scale: y }) =>
                            ScalarTy::Numeric { scale: if x >= y { x } else { y } },
                        _ => a.ty,
                    },
                    nullable: a.nullable || b.nullable,
                })
            } else {
                None
            },
        _ => None,
    }
}

pub open spec fn same_shape(a: ScalarTy, b: ScalarTy) -> bool {
    match (a, b) {
        (ScalarTy::Numeric { .. }, ScalarTy::Numeric { .. }) => true,
        _ => a == b,
    }
}

#[derive(Clone, Copy)]
pub enum ScalarFn {
    /// `int4 / int4` (truncating; 22012 on a zero divisor).
    DivInt4,
    /// `int8 / int8`.
    DivInt8,
    /// `numeric / numeric` (PostgreSQL `select_div_scale`, rounded half away from zero).
    DivNumeric,
    /// `s LIKE p ESCAPE esc` -> bool.
    Like,
    /// `SUBSTRING(s FROM start)`.
    Substring2,
    /// `SUBSTRING(s FROM start FOR len)`.
    Substring3,
    /// `EXTRACT(YEAR FROM d)` -> numeric scale 0.
    ExtractYear,
    ExtractMonth,
    ExtractDay,
    /// `char(n)` value padded with spaces to `n` characters.
    PadBpchar,
}

Expr::Call { f, args } => match eval_exprs(db, env, args) {
    Err(err) => Err(err),
    Ok(vs) => apply_fn(f, vs),
},

pub open spec fn apply_fn(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    match f {
        ScalarFn::DivInt4 | ScalarFn::DivInt8 | ScalarFn::DivNumeric => div::apply_div(f, args),
        ScalarFn::Like => like::apply_like(f, args),
        ScalarFn::Substring2 | ScalarFn::Substring3 => substring::apply_substring(f, args),
        ScalarFn::ExtractYear | ScalarFn::ExtractMonth | ScalarFn::ExtractDay => extract::apply_extract(f, args),
        ScalarFn::PadBpchar => pad::apply_pad(f, args),
    }
}

Expr::Call { f, args } => match type_exprs(schema, env, args) {
    Some(ts) => type_fn(f, ts),
    None => None,
},

pub open spec fn type_fn(f: ScalarFn, args: Seq<ColTy>) -> Option<ColTy> {
    match f {
        ScalarFn::DivInt4 | ScalarFn::DivInt8 | ScalarFn::DivNumeric => div::type_div(f, args),
        ScalarFn::Like => like::type_like(f, args),
        ScalarFn::Substring2 | ScalarFn::Substring3 => substring::type_substring(f, args),
        ScalarFn::ExtractYear | ScalarFn::ExtractMonth | ScalarFn::ExtractDay => extract::type_extract(f, args),
        ScalarFn::PadBpchar => pad::type_pad(f, args),
    }
}

pub open spec fn fits_fn(f: ScalarFn, args: Seq<Val>) -> bool {
    match f {
        ScalarFn::DivInt4 | ScalarFn::DivInt8 | ScalarFn::DivNumeric => div::fits_div(f, args),
        ScalarFn::Like => like::fits_like(f, args),
        ScalarFn::Substring2 | ScalarFn::Substring3 => substring::fits_substring(f, args),
        ScalarFn::ExtractYear | ScalarFn::ExtractMonth | ScalarFn::ExtractDay => extract::fits_extract(f, args),
        ScalarFn::PadBpchar => pad::fits_pad(f, args),
    }
}

pub open spec fn apply_like(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    if args.len() == 3 { like_value(args[0], args[1], args[2]) } else { Err(SqlError::TypeError) }
}

pub open spec fn like_value(s: Val, p: Val, e: Val) -> Result<Val, SqlError> {
    if p is Null || e is Null {
        Ok(Val::Null)
    } else {
        match (p, e) {
            (Val::Text(pb), Val::Text(eb)) => {
                let ec = chars(eb);
                if ec.len() > 1 {
                    Err(SqlError::InvalidEscapeSequence)
                } else {
                    match s {
                        Val::Null => Ok(Val::Null),
                        Val::Text(sb) => match like_mt(chars(sb), like_tokens(chars(pb), escape_of(ec), 0), 0, 0) {
                            Ok(r) => Ok(Val::Bool(r is Match)),
                            Err(err) => Err(err),
                        },
                        _ => Err(SqlError::TypeError),
                    }
                }
            },
            _ => Err(SqlError::TypeError),
        }
    }
}

pub enum LikeTok {
    /// A character matched literally (bytewise).
    Lit(Seq<u8>),
    /// `_`: exactly one character.
    One,
    /// `%`: any sequence of characters.
    Any,
    /// An escape character with nothing after it (only ever the last token).
    Dangling,
}

pub open spec fn like_tokens(pc: Seq<Seq<u8>>, esc: Option<Seq<u8>>, k: int) -> Seq<LikeTok>
    decreases pc.len() - k,
{
    if k < 0 || k >= pc.len() {
        Seq::empty()
    } else if esc == Some(pc[k]) {
        if k + 1 >= pc.len() {
            seq![LikeTok::Dangling]
        } else {
            seq![LikeTok::Lit(pc[k + 1])] + like_tokens(pc, esc, k + 2)
        }
    } else if pc[k] == pct() {
        seq![LikeTok::Any] + like_tokens(pc, esc, k + 1)
    } else if pc[k] == underscore() {
        seq![LikeTok::One] + like_tokens(pc, esc, k + 1)
    } else {
        seq![LikeTok::Lit(pc[k])] + like_tokens(pc, esc, k + 1)
    }
}

pub enum LikeRes {
    Match,
    NoMatch,
    /// No match here nor at any later text position (PostgreSQL's early exit).
    Abort,
}

pub open spec fn like_mt(t: Seq<Seq<u8>>, p: Seq<LikeTok>, i: int, j: int) -> Result<LikeRes, SqlError>
    decreases p.len() - j, 0int, t.len() - i,
{
    if 0 <= i < t.len() && 0 <= j < p.len() {
        match p[j] {
            LikeTok::Dangling => Err(SqlError::InvalidEscapeSequence),
            LikeTok::Lit(c) => if t[i] == c { like_mt(t, p, i + 1, j + 1) } else { Ok(LikeRes::NoMatch) },
            LikeTok::One => like_mt(t, p, i + 1, j + 1),
            LikeTok::Any => like_any(t, p, i, j + 1),
        }
    } else if 0 <= i < t.len() {
        // End of pattern, text left.
        Ok(LikeRes::NoMatch)
    } else {
        // End of text: match iff only `%`s are left.
        like_end(p, j)
    }
}

pub open spec fn like_any(t: Seq<Seq<u8>>, p: Seq<LikeTok>, i: int, j: int) -> Result<LikeRes, SqlError>
    decreases p.len() - j, 2int, t.len() - i,
{
    if 0 <= j < p.len() {
        match p[j] {
            LikeTok::Any => like_any(t, p, i, j + 1),
            LikeTok::One => if 0 <= i < t.len() { like_any(t, p, i + 1, j + 1) } else { Ok(LikeRes::Abort) },
            LikeTok::Dangling => Err(SqlError::InvalidEscapeSequence),
            LikeTok::Lit(_) => like_scan(t, p, i, j),
        }
    } else {
        Ok(LikeRes::Match)
    }
}

blocks.doc:
After a `%` (the tokens before `j` are consumed): skip further `%`s and `_`s (each `_` takes one character;
running out of text is `Abort`), then a trailing run matches, a dangling escape raises, and a literal starts
the scan for a position where the rest matches.

blocks.code:
pub open spec fn like_scan(t: Seq<Seq<u8>>, p: Seq<LikeTok>, k: int, j: int) -> Result<LikeRes, SqlError>
    decreases p.len() - j, 1int, t.len() - k,
{
    if 0 <= k < t.len() {
        match like_mt(t, p, k, j) {
            Ok(LikeRes::NoMatch) => like_scan(t, p, k + 1, j),
            r => r,
        }
    } else {
        Ok(LikeRes::Abort)
    }
}

pub open spec fn like_end(p: Seq<LikeTok>, j: int) -> Result<LikeRes, SqlError>
    decreases p.len() - j,
{
    if 0 <= j < p.len() {
        match p[j] {
            LikeTok::Any => like_end(p, j + 1),
            _ => Ok(LikeRes::Abort),
        }
    } else {
        Ok(LikeRes::Match)
    }
}

pub open spec fn like_std(t: Seq<Seq<u8>>, p: Seq<LikeTok>, i: int, j: int) -> bool
    decreases (t.len() - i) + (p.len() - j),
{
    if i < 0 || i > t.len() || j < 0 {
        false
    } else if j >= p.len() {
        i == t.len()
    } else {
        match p[j] {
            LikeTok::Lit(c) => i < t.len() && t[i] == c && like_std(t, p, i + 1, j + 1),
            LikeTok::One => i < t.len() && like_std(t, p, i + 1, j + 1),
            LikeTok::Any => like_std(t, p, i, j + 1) || (i < t.len() && like_std(t, p, i + 1, j)),
            LikeTok::Dangling => false,
        }
    }
}

pub open spec fn escape_of(ec: Seq<Seq<u8>>) -> Option<Seq<u8>> {
    if ec.len() == 0 { None } else { Some(ec[0]) }
}

pub open spec fn apply_pad(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    if args.len() != 2 {
        Err(SqlError::TypeError)
    } else if args[0] is Null || args[1] is Null {
        Ok(Val::Null)
    } else {
        match (args[0], args[1]) {
            (Val::Text(b), Val::Int(n)) => Ok(Val::Text(b + spaces(n - chars(b).len()))),
            _ => Err(SqlError::TypeError),
        }
    }
}

pub open spec fn spaces(k: int) -> Seq<u8> {
    Seq::new(if k > 0 { k as nat } else { 0 }, |i: int| 0x20u8)
}

pub open spec fn type_like(f: ScalarFn, args: Seq<ColTy>) -> Option<ColTy> {
    if args.len() == 3 && args[0].ty is Text && args[1].ty is Text && args[2].ty is Text {
        Some(ColTy { ty: ScalarTy::Bool, nullable: args[0].nullable || args[1].nullable || args[2].nullable })
    } else {
        None
    }
}

pub open spec fn type_pad(f: ScalarFn, args: Seq<ColTy>) -> Option<ColTy> {
    if args.len() == 2 && args[0].ty is Text && args[1].ty is Int4 {
        Some(ColTy { ty: ScalarTy::Text, nullable: args[0].nullable || args[1].nullable })
    } else {
        None
    }
}

pub open spec fn fits_like(f: ScalarFn, args: Seq<Val>) -> bool {
    true
}

pub open spec fn fits_pad(f: ScalarFn, args: Seq<Val>) -> bool {
    true
}

pub open spec fn apply_substring(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    if args.len() != substring_arity(f) {
        Err(SqlError::TypeError)
    } else if exists|k: int| 0 <= k < args.len() && #[trigger] args[k] is Null {
        Ok(Val::Null)
    } else {
        substring_value(f, args)
    }
}

pub open spec fn substring_value(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    match f {
        ScalarFn::Substring3 => match (args[0], args[1], args[2]) {
            (Val::Text(b), Val::Int(start), Val::Int(len)) =>
                if len < 0 {
                    Err(SqlError::SubstringError)
                } else {
                    Ok(Val::Text(char_range(chars(b), start, substring_end(start, len))))
                },
            _ => Err(SqlError::TypeError),
        },
        _ => match (args[0], args[1]) {
            (Val::Text(b), Val::Int(start)) => Ok(Val::Text(char_range(chars(b), start, None))),
            _ => Err(SqlError::TypeError),
        },
    }
}

pub open spec fn char_range(cs: Seq<Seq<u8>>, start: int, end: Option<int>) -> Seq<u8> {
    let n = cs.len() as int;
    let lo = if start < 1 { 0 } else if start - 1 > n { n } else { start - 1 };
    let hi = match end {
        None => n,
        Some(e) => if e - 1 < lo { lo } else if e - 1 > n { n } else { e - 1 },
    };
    concat(cs.subrange(lo, hi))
}

pub open spec fn substring_end(start: int, len: int) -> Option<int> {
    if start + len > int4_max() { None } else { Some(start + len) }
}

pub open spec fn substring_arity(f: ScalarFn) -> nat {
    match f { ScalarFn::Substring3 => 3, _ => 2 }
}

pub open spec fn type_substring(f: ScalarFn, args: Seq<ColTy>) -> Option<ColTy> {
    if args.len() == substring_arity(f) && args[0].ty is Text && args[1].ty is Int4
        && (args.len() == 2 || args[2].ty is Int4) {
        Some(ColTy {
            ty: ScalarTy::Text,
            nullable: args[0].nullable || args[1].nullable || (args.len() == 3 && args[2].nullable),
        })
    } else {
        None
    }
}

pub open spec fn fits_substring(f: ScalarFn, args: Seq<Val>) -> bool {
    true
}

Expr::AddInterval { arg, months, days, micros } => match eval_expr(db, env, *arg) {
    Err(err) => Err(err),
    Ok(v) => add_interval(v, months, days, micros),
},

pub open spec fn add_interval(a: Val, months: i32, days: i32, micros: i64) -> Result<Val, SqlError> {
    match a {
        Val::Null => Ok(Val::Null),
        Val::Ts(t) => match ts_add_interval(t, months as int, days as int, micros as int) {
            Ok(r) => Ok(Val::Ts(r)),
            Err(e) => Err(e),
        },
        _ => Err(SqlError::TypeError),
    }
}

pub open spec fn ts_add_interval(t: int, months: int, days: int, micros: int) -> Result<int, SqlError> {
    let r1 = if months != 0 { ts_add_months(t, months) } else { Ok(t) };
    match r1 {
        Err(e) => Err(e),
        Ok(t1) => {
            let r2 = if days != 0 { ts_result(t1 + days * usecs_per_day()) } else { Ok(t1) };
            match r2 {
                Err(e) => Err(e),
                Ok(t2) => ts_result(t2 + micros),
            }
        },
    }
}

pub open spec fn ts_add_months(t: int, months: int) -> Result<int, SqlError> {
    let day = t / usecs_per_day();
    let tod = t % usecs_per_day();
    let ymd = civil_from_date(day);
    let total = ymd.0 * 12 + (ymd.1 - 1) + months;
    let y2 = total / 12;
    let m2 = total % 12 + 1;
    let d2 = if ymd.2 <= days_in_month(y2, m2) { ymd.2 } else { days_in_month(y2, m2) };
    ts_result(date_from_civil(y2, m2, d2) * usecs_per_day() + tod)
}

pub open spec fn apply_extract(f: ScalarFn, args: Seq<Val>) -> Result<Val, SqlError> {
    if args.len() != 1 {
        Err(SqlError::TypeError)
    } else {
        match args[0] {
            Val::Null => Ok(Val::Null),
            Val::Date(d) => Ok(Val::Num { coeff: extract_field(f, civil_from_date(d)), scale: 0 }),
            Val::Ts(t) => Ok(Val::Num { coeff: extract_field(f, civil_from_date(t / usecs_per_day())), scale: 0 }),
            _ => Err(SqlError::TypeError),
        }
    }
}

pub open spec fn extract_field(f: ScalarFn, ymd: (int, int, int)) -> int {
    match f {
        ScalarFn::ExtractYear => if ymd.0 > 0 { ymd.0 } else { ymd.0 - 1 },
        ScalarFn::ExtractMonth => ymd.1,
        _ => ymd.2,
    }
}

Expr::AddInterval { arg, months, days, micros } => match type_expr(schema, env, *arg) {
    Some(t) => if t.ty is Timestamp { Some(t) } else { None },
    None => None,
},

pub open spec fn type_extract(f: ScalarFn, args: Seq<ColTy>) -> Option<ColTy> {
    if args.len() == 1 && (args[0].ty is Date || args[0].ty is Timestamp) {
        Some(ColTy { ty: ScalarTy::Numeric { scale: 0 }, nullable: args[0].nullable })
    } else {
        None
    }
}

pub open spec fn fits_extract(f: ScalarFn, args: Seq<Val>) -> bool {
    true
}

Expr::Subquery(q) => match eval_query(db, env, *q) {
    Err(err) => Err(err),
    Ok(rows) => subquery_value(rows),
},

pub open spec fn subquery_value(rows: Relation) -> Result<Val, SqlError> {
    if rows.len() == 0 {
        Ok(Val::Null)
    } else if rows.len() == 1 {
        first_col(rows[0])
    } else {
        Err(SqlError::CardinalityViolation)
    }
}

pub open spec fn first_col(r: Row) -> Result<Val, SqlError> {
    if r.len() > 0 { Ok(r[0]) } else { Err(SqlError::TypeError) }
}

pub open spec fn subquery_ty(q: Option<Seq<ColTy>>) -> Option<ColTy> {
    match q {
        Some(tys) => if tys.len() == 1 { Some(ColTy { ty: tys[0].ty, nullable: true }) } else { None },
        None => None,
    }
}

pub enum Pred {
    Cmp { op: CmpOp, a: Expr, b: Expr },
    And(Box<Pred>, Box<Pred>),
    Or(Box<Pred>, Box<Pred>),
    Not(Box<Pred>),
    /// `e IS NULL` (two-valued). `IS NOT NULL` is `Not(IsNull(e))`.
    IsNull(Expr),
    /// A boolean expression used as a condition (NULL is `Unknown`).
    OfBool(Expr),
    /// `EXISTS (q)`; `q` sees the current environment as its context (correlation).
    Exists(Box<Query>),
    /// `e op ANY (q)` (`IN` is `AnyCmp` with `Eq`); `q` sees the current environment as its context.
    AnyCmp { op: CmpOp, e: Expr, q: Box<Query> },
}

pub open spec fn eval_pred(db: Database, env: Row, p: Pred) -> Result<Truth, SqlError>
    decreases p,
{
    match p {
        Pred::Cmp { op, a, b } => match eval_expr(db, env, a) {
            Err(err) => Err(err),
            Ok(va) => match eval_expr(db, env, b) {
                Err(err) => Err(err),
                Ok(vb) => cmp_truth(op, va, vb),
            },
        },
        Pred::And(a, b) => match eval_pred(db, env, *a) {
            Err(err) => Err(err),
            Ok(ta) => match eval_pred(db, env, *b) {
                Err(err) => Err(err),
                Ok(tb) => Ok(truth_and(ta, tb)),
            },
        },
        Pred::Or(a, b) => match eval_pred(db, env, *a) {
            Err(err) => Err(err),
            Ok(ta) => match eval_pred(db, env, *b) {
                Err(err) => Err(err),
                Ok(tb) => Ok(truth_or(ta, tb)),
            },
        },
        Pred::Not(a) => match eval_pred(db, env, *a) {
            Err(err) => Err(err),
            Ok(t) => Ok(truth_not(t)),
        },
        Pred::IsNull(e) => match eval_expr(db, env, e) {
            Err(err) => Err(err),
            Ok(v) => Ok(truth_of(v is Null)),
        },
        Pred::OfBool(e) => match eval_expr(db, env, e) {
            Err(err) => Err(err),
            Ok(v) => truth_of_val(v),
        },
        Pred::Exists(q) => match eval_query(db, env, *q) {
            Err(err) => Err(err),
            Ok(rows) => Ok(truth_of(rows.len() > 0)),
        },
        Pred::AnyCmp { op, e, q } => match eval_expr(db, env, e) {
            Err(err) => Err(err),
            Ok(v) => match eval_query(db, env, *q) {
                Err(err) => Err(err),
                Ok(rows) => any_cmp_truth(op, v, rows),
            },
        },
    }
}

pub open spec fn type_pred(schema: Schema, env: Seq<ColTy>, p: Pred) -> bool
    decreases p,
{
    match p {
        Pred::Cmp { op, a, b } => match (type_expr(schema, env, a), type_expr(schema, env, b)) {
            (Some(ta), Some(tb)) => family(ta.ty) == family(tb.ty),
            _ => false,
        },
        Pred::And(a, b) => type_pred(schema, env, *a) && type_pred(schema, env, *b),
        Pred::Or(a, b) => type_pred(schema, env, *a) && type_pred(schema, env, *b),
        Pred::Not(a) => type_pred(schema, env, *a),
        Pred::IsNull(e) => type_expr(schema, env, e) is Some,
        Pred::OfBool(e) => match type_expr(schema, env, e) {
            Some(t) => t.ty is Bool,
            None => false,
        },
        Pred::Exists(q) => type_query(schema, env, *q) is Some,
        Pred::AnyCmp { op, e, q } => any_cmp_ok(op, type_expr(schema, env, e), type_query(schema, env, *q)),
    }
}

Pred::Cmp { op, a, b } => match eval_expr(db, env, a) {
    Err(err) => Err(err),
    Ok(va) => match eval_expr(db, env, b) {
        Err(err) => Err(err),
        Ok(vb) => cmp_truth(op, va, vb),
    },
},

pub open spec fn cmp_truth(op: CmpOp, a: Val, b: Val) -> Result<Truth, SqlError> {
    if a is Null || b is Null {
        Ok(Truth::Unknown)
    } else {
        match compare(a, b) {
            Some(c) => Ok(truth_of(cmp_holds(op, c))),
            None => Err(SqlError::TypeError),
        }
    }
}

blocks.doc:
Exact order of two non-NULL values of one comparison family: `Some(-1 | 0 | 1)`, or `None` across
families. Families: boolean; `int4/int8/numeric` (exact value order, as PostgreSQL's cross-type operators);
`date/timestamp` (exact, dates at midnight); text (bytes).

blocks.code:
pub open spec fn cmp_holds(op: CmpOp, c: int) -> bool {
    match op {
        CmpOp::Eq => c == 0,
        CmpOp::Ne => c != 0,
        CmpOp::Lt => c < 0,
        CmpOp::Le => c <= 0,
        CmpOp::Gt => c > 0,
        CmpOp::Ge => c >= 0,
    }
}

Pred::Cmp { op, a, b } => match (type_expr(schema, env, a), type_expr(schema, env, b)) {
    (Some(ta), Some(tb)) => family(ta.ty) == family(tb.ty),
    _ => false,
},

#[derive(Clone, Copy)]
pub enum Truth {
    True,
    False,
    Unknown,
}

pub open spec fn truth_and(a: Truth, b: Truth) -> Truth {
    match (a, b) {
        (Truth::False, _) => Truth::False,
        (_, Truth::False) => Truth::False,
        (Truth::True, Truth::True) => Truth::True,
        _ => Truth::Unknown,
    }
}

pub open spec fn truth_or(a: Truth, b: Truth) -> Truth {
    match (a, b) {
        (Truth::True, _) => Truth::True,
        (_, Truth::True) => Truth::True,
        (Truth::False, Truth::False) => Truth::False,
        _ => Truth::Unknown,
    }
}

pub open spec fn truth_not(a: Truth) -> Truth {
    match a {
        Truth::True => Truth::False,
        Truth::False => Truth::True,
        Truth::Unknown => Truth::Unknown,
    }
}

pub open spec fn truth_of(b: bool) -> Truth {
    if b { Truth::True } else { Truth::False }
}

pub open spec fn truth_of_val(a: Val) -> Result<Truth, SqlError> {
    match a {
        Val::Null => Ok(Truth::Unknown),
        Val::Bool(b) => Ok(truth_of(b)),
        _ => Err(SqlError::TypeError),
    }
}

Pred::And(a, b) => match eval_pred(db, env, *a) {
    Err(err) => Err(err),
    Ok(ta) => match eval_pred(db, env, *b) {
        Err(err) => Err(err),
        Ok(tb) => Ok(truth_and(ta, tb)),
    },
},

Pred::Or(a, b) => match eval_pred(db, env, *a) {
    Err(err) => Err(err),
    Ok(ta) => match eval_pred(db, env, *b) {
        Err(err) => Err(err),
        Ok(tb) => Ok(truth_or(ta, tb)),
    },
},

Pred::Not(a) => match eval_pred(db, env, *a) {
    Err(err) => Err(err),
    Ok(t) => Ok(truth_not(t)),
},

Pred::OfBool(e) => match eval_expr(db, env, e) {
    Err(err) => Err(err),
    Ok(v) => truth_of_val(v),
},

Pred::OfBool(e) => match type_expr(schema, env, e) {
    Some(t) => t.ty is Bool,
    None => false,
},

Pred::IsNull(e) => match eval_expr(db, env, e) {
    Err(err) => Err(err),
    Ok(v) => Ok(truth_of(v is Null)),
},

Pred::Exists(q) => match eval_query(db, env, *q) {
    Err(err) => Err(err),
    Ok(rows) => Ok(truth_of(rows.len() > 0)),
},

Pred::AnyCmp { op, e, q } => match eval_expr(db, env, e) {
    Err(err) => Err(err),
    Ok(v) => match eval_query(db, env, *q) {
        Err(err) => Err(err),
        Ok(rows) => any_cmp_truth(op, v, rows),
    },
},

pub open spec fn any_cmp_truth(op: CmpOp, v: Val, rows: Relation) -> Result<Truth, SqlError>
    decreases rows.len(),
{
    if rows.len() == 0 {
        Ok(Truth::False)
    } else {
        match any_cmp_truth(op, v, rows.drop_last()) {
            Err(err) => Err(err),
            Ok(t) => match first_col(rows.last()) {
                Err(err) => Err(err),
                Ok(x) => match cmp_truth(op, v, x) {
                    Err(err) => Err(err),
                    Ok(u) => Ok(truth_or(t, u)),
                },
            },
        }
    }
}

pub open spec fn any_cmp_ok(op: CmpOp, e: Option<ColTy>, q: Option<Seq<ColTy>>) -> bool {
    match (e, q) {
        (Some(t), Some(tys)) => tys.len() == 1 && family(t.ty) == family(tys[0].ty),
        _ => false,
    }
}

pub enum Query {
    /// Base table by id (DDL order).
    Table(nat),
    /// `WHERE` / `HAVING` / `ON` of inner joins: keep rows whose condition is `True`.
    Filter { pred: Pred, input: Box<Query> },
    /// `SELECT e1, ..., en` (one output row per input row).
    Project { exprs: Seq<Expr>, input: Box<Query> },
    /// Cross product (left-major); inner join = `Filter` over `Product`. Non-lateral: `right` sees only `ctx`.
    Product { left: Box<Query>, right: Box<Query> },
    /// `left LEFT JOIN right ON on`: unmatched left rows are padded with NULLs.
    LeftJoin { left: Box<Query>, right: Box<Query>, on: Pred },
    /// Aggregation without GROUP BY: exactly one row, also on empty input.
    Aggregate { aggs: Seq<Agg>, input: Box<Query> },
    /// `GROUP BY keys`: one row `keys ++ aggs` per class of not-distinct key tuples (`spec::equality`: NULLs
    /// group together, numerics by value), groups in first-occurrence order; the first member's key represents
    /// the group.
    GroupBy { keys: Seq<Expr>, aggs: Seq<Agg>, input: Box<Query> },
    /// `SELECT DISTINCT`: one row per not-distinct class (`spec::equality`), first occurrence.
    Distinct(Box<Query>),
}

pub open spec fn eval_query(db: Database, ctx: Row, q: Query) -> Result<Relation, SqlError>
    decreases q,
{
    match q {
        Query::Table(t) => if t < db.tables.len() { Ok(db.tables[t as int]) } else { Err(SqlError::TypeError) },
        Query::Filter { pred, input } => match eval_query(db, ctx, *input) {
            Err(err) => Err(err),
            Ok(rows) => match collect(Seq::new(rows.len(), |i: int| eval_pred(db, ctx + rows[i], pred))) {
                Err(err) => Err(err),
                Ok(truths) => Ok(keep_true(rows, truths)),
            },
        },
        Query::Project { exprs, input } => match eval_query(db, ctx, *input) {
            Err(err) => Err(err),
            Ok(rows) => collect(Seq::new(rows.len(), |i: int| eval_exprs(db, ctx + rows[i], exprs))),
        },
        Query::Product { left, right } => match eval_query(db, ctx, *left) {
            Err(err) => Err(err),
            Ok(l) => match eval_query(db, ctx, *right) {
                Err(err) => Err(err),
                Ok(r) => Ok(product_rows(l, r)),
            },
        },
        Query::LeftJoin { left, right, on } => match eval_query(db, ctx, *left) {
            Err(err) => Err(err),
            Ok(l) => match eval_query(db, ctx, *right) {
                Err(err) => Err(err),
                Ok(r) => match collect(Seq::new(l.len(), |i: int|
                    collect(Seq::new(r.len(), |j: int| eval_pred(db, ctx + l[i] + r[j], on))))) {
                    Err(err) => Err(err),
                    Ok(truths) => Ok(left_join_rows(l, r, truths, query_arity(db.schema, *right))),
                },
            },
        },
        Query::Aggregate { aggs, input } => match eval_query(db, ctx, *input) {
            Err(err) => Err(err),
            Ok(rows) => match collect(Seq::new(rows.len(), |i: int| agg_args(db, ctx + rows[i], aggs))) {
                Err(err) => Err(err),
                Ok(args) => match agg_row(aggs, args) {
                    Err(err) => Err(err),
                    Ok(row) => Ok(seq![row]),
                },
            },
        },
        Query::GroupBy { keys, aggs, input } => match eval_query(db, ctx, *input) {
            Err(err) => Err(err),
            Ok(rows) => match collect(Seq::new(rows.len(), |i: int|
                match eval_exprs(db, ctx + rows[i], keys) {
                    Err(err) => Err(err),
                    Ok(k) => match agg_args(db, ctx + rows[i], aggs) {
                        Err(err) => Err(err),
                        Ok(a) => Ok((k, a)),
                    },
                })) {
                Err(err) => Err(err),
                Ok(prepared) => group_rows(
                    aggs,
                    prepared.map_values(|p: (Row, Row)| p.0),
                    prepared.map_values(|p: (Row, Row)| p.1),
                ),
            },
        },
        Query::Distinct(input) => match eval_query(db, ctx, *input) {
            Err(err) => Err(err),
            Ok(rows) => distinct_query_rows(rows),
        },
    }
}

pub open spec fn type_query(schema: Schema, ctx: Seq<ColTy>, q: Query) -> Option<Seq<ColTy>>
    decreases q,
{
    match q {
        Query::Table(t) => if t < schema.len() { Some(table_tys(schema[t as int])) } else { None },
        Query::Filter { pred, input } => match type_query(schema, ctx, *input) {
            Some(tys) => if type_pred(schema, ctx + tys, pred) { Some(tys) } else { None },
            None => None,
        },
        Query::Project { exprs, input } => match type_query(schema, ctx, *input) {
            Some(tys) => type_exprs(schema, ctx + tys, exprs),
            None => None,
        },
        Query::Product { left, right } => match (type_query(schema, ctx, *left), type_query(schema, ctx, *right)) {
            (Some(l), Some(r)) => Some(l + r),
            _ => None,
        },
        Query::LeftJoin { left, right, on } => match (type_query(schema, ctx, *left), type_query(schema, ctx, *right)) {
            (Some(l), Some(r)) => if type_pred(schema, ctx + l + r, on) { Some(l + nullable_all(r)) } else { None },
            _ => None,
        },
        Query::Aggregate { aggs, input } => match type_query(schema, ctx, *input) {
            Some(tys) => type_aggs(schema, ctx + tys, aggs),
            None => None,
        },
        Query::GroupBy { keys, aggs, input } => match type_query(schema, ctx, *input) {
            Some(tys) => match (type_exprs(schema, ctx + tys, keys), type_aggs(schema, ctx + tys, aggs)) {
                (Some(k), Some(a)) => Some(k + a),
                _ => None,
            },
            None => None,
        },
        Query::Distinct(input) => distinct_ty(type_query(schema, ctx, *input)),
    }
}

pub open spec fn table_tys(t: TableSchema) -> Seq<ColTy> {
    t.columns.map_values(|c: Column| col_ty_of(c))
}

Query::Filter { pred, input } => match eval_query(db, ctx, *input) {
    Err(err) => Err(err),
    Ok(rows) => match collect(Seq::new(rows.len(), |i: int| eval_pred(db, ctx + rows[i], pred))) {
        Err(err) => Err(err),
        Ok(truths) => Ok(keep_true(rows, truths)),
    },
},

pub open spec fn keep_true(rows: Seq<Row>, truths: Seq<Truth>) -> Seq<Row>
    decreases rows.len(),
{
    if rows.len() == 0 || truths.len() == 0 {
        Seq::empty()
    } else {
        let init = keep_true(rows.drop_last(), truths.drop_last());
        if truths.last() is True { init.push(rows.last()) } else { init }
    }
}

Query::Filter { pred, input } => match type_query(schema, ctx, *input) {
    Some(tys) => if type_pred(schema, ctx + tys, pred) { Some(tys) } else { None },
    None => None,
},

Query::Project { exprs, input } => match eval_query(db, ctx, *input) {
    Err(err) => Err(err),
    Ok(rows) => collect(Seq::new(rows.len(), |i: int| eval_exprs(db, ctx + rows[i], exprs))),
},

Query::Project { exprs, input } => match type_query(schema, ctx, *input) {
    Some(tys) => type_exprs(schema, ctx + tys, exprs),
    None => None,
},

Query::Product { left, right } => match eval_query(db, ctx, *left) {
    Err(err) => Err(err),
    Ok(l) => match eval_query(db, ctx, *right) {
        Err(err) => Err(err),
        Ok(r) => Ok(product_rows(l, r)),
    },
},

pub open spec fn product_rows(left: Seq<Row>, right: Seq<Row>) -> Seq<Row>
    decreases left.len(),
{
    if left.len() == 0 {
        Seq::empty()
    } else {
        product_rows(left.drop_last(), right) + right.map_values(|r: Row| left.last() + r)
    }
}

Query::Product { left, right } => match (type_query(schema, ctx, *left), type_query(schema, ctx, *right)) {
    (Some(l), Some(r)) => Some(l + r),
    _ => None,
},

Query::LeftJoin { left, right, on } => match eval_query(db, ctx, *left) {
    Err(err) => Err(err),
    Ok(l) => match eval_query(db, ctx, *right) {
        Err(err) => Err(err),
        Ok(r) => match collect(Seq::new(l.len(), |i: int|
            collect(Seq::new(r.len(), |j: int| eval_pred(db, ctx + l[i] + r[j], on))))) {
            Err(err) => Err(err),
            Ok(truths) => Ok(left_join_rows(l, r, truths, query_arity(db.schema, *right))),
        },
    },
},

pub open spec fn left_join_rows(left: Seq<Row>, right: Seq<Row>, truths: Seq<Seq<Truth>>, right_arity: nat) -> Seq<Row>
    decreases left.len(),
{
    if left.len() == 0 || truths.len() == 0 {
        Seq::empty()
    } else {
        left_join_rows(left.drop_last(), right, truths.drop_last(), right_arity)
            + left_join_one(left.last(), right, truths.last(), right_arity)
    }
}

pub open spec fn left_join_one(l: Row, right: Seq<Row>, truths: Seq<Truth>, right_arity: nat) -> Seq<Row> {
    let matched = keep_true(right, truths);
    if matched.len() == 0 {
        seq![l + null_row(right_arity)]
    } else {
        matched.map_values(|r: Row| l + r)
    }
}

pub open spec fn null_row(n: nat) -> Row {
    Seq::new(n, |i: int| Val::Null)
}

Query::LeftJoin { left, right, on } => match (type_query(schema, ctx, *left), type_query(schema, ctx, *right)) {
    (Some(l), Some(r)) => if type_pred(schema, ctx + l + r, on) { Some(l + nullable_all(r)) } else { None },
    _ => None,
},

pub open spec fn nullable_all(tys: Seq<ColTy>) -> Seq<ColTy> {
    tys.map_values(|t: ColTy| ColTy { ty: t.ty, nullable: true })
}

Query::Distinct(input) => match eval_query(db, ctx, *input) {
    Err(err) => Err(err),
    Ok(rows) => distinct_query_rows(rows),
},

pub open spec fn distinct_query_rows(rows: Relation) -> Result<Relation, SqlError> {
    Ok(distinct_rows(rows))
}

pub open spec fn distinct_rows(rows: Seq<Row>) -> Seq<Row>
    decreases rows.len(),
{
    if rows.len() == 0 {
        Seq::empty()
    } else {
        let d = distinct_rows(rows.drop_last());
        if has_not_distinct(d, rows.last()) { d } else { d.push(rows.last()) }
    }
}

pub open spec fn has_not_distinct(rows: Seq<Row>, r: Row) -> bool
    decreases rows.len(),
{
    rows.len() > 0 && (row_not_distinct(rows.last(), r) || has_not_distinct(rows.drop_last(), r))
}

pub open spec fn row_not_distinct(r: Row, s: Row) -> bool {
    r.len() == s.len() && forall|i: int| 0 <= i < r.len() ==> val_not_distinct(#[trigger] r[i], s[i])
}

pub open spec fn val_not_distinct(a: Val, b: Val) -> bool {
    if a is Null || b is Null {
        a is Null && b is Null
    } else {
        compare(a, b) == Some(0int)
    }
}

pub open spec fn distinct_ty(q: Option<Seq<ColTy>>) -> Option<Seq<ColTy>> {
    q
}

pub enum Agg {
    CountStar,
    Count(Expr),
    Sum { kind: NumKind, arg: Expr },
    Min(Expr),
    Max(Expr),
    Avg { kind: NumKind, arg: Expr },
    /// `agg(DISTINCT ...)`: the inner aggregate over the non-NULL values, one per not-distinct class
    /// (`spec::equality::distinct_vals`).
    DistinctAgg(Box<Agg>),
}

Query::Aggregate { aggs, input } => match eval_query(db, ctx, *input) {
    Err(err) => Err(err),
    Ok(rows) => match collect(Seq::new(rows.len(), |i: int| agg_args(db, ctx + rows[i], aggs))) {
        Err(err) => Err(err),
        Ok(args) => match agg_row(aggs, args) {
            Err(err) => Err(err),
            Ok(row) => Ok(seq![row]),
        },
    },
},

pub open spec fn agg_row(aggs: Seq<Agg>, args: Seq<Row>) -> Result<Row, SqlError> {
    collect(Seq::new(aggs.len(), |j: int| agg_value(aggs[j], column(args, j))))
}

pub open spec fn agg_value(a: Agg, vs: Seq<Val>) -> Result<Val, SqlError>
    decreases a,
{
    match a {
        Agg::CountStar => int_result(IntKind::Int8, vs.len() as int),
        Agg::Count(_) => int_result(IntKind::Int8, count_non_null(vs) as int),
        Agg::Sum { kind, arg } => {
            if !all_of_kind(kind, vs) {
                Err(SqlError::TypeError)
            } else if count_non_null(vs) == 0 {
                Ok(Val::Null)
            } else {
                match kind {
                    NumKind::Int4 => int_result(IntKind::Int8, int_sum(vs)),
                    NumKind::Int8 => num_result(int_sum(vs), 0),
                    NumKind::Numeric => {
                        let s = num_sum(vs);
                        num_result(s.0, s.1)
                    },
                }
            }
        },
        Agg::Min(_) => min_value(vs),
        Agg::Max(_) => max_value(vs),
        Agg::Avg { kind, arg } => avg_value(kind, vs),
        Agg::DistinctAgg(inner) => agg_value(*inner, distinct_vals(vs)),
    }
}

blocks.doc:
Final value of one aggregate over its argument values (one per input row of the group; `CountStar`
ignores them). Range checks apply only to the final value. MIN/MAX/AVG are defined in `spec::aggs`;
`DistinctAgg` applies its inner aggregate to the distinct non-NULL values.

blocks.code:
pub open spec fn column(rows: Seq<Row>, j: int) -> Seq<Val> {
    rows.map_values(|r: Row| r[j])
}

pub open spec fn agg_args(db: Database, env: Row, aggs: Seq<Agg>) -> Result<Row, SqlError>
    decreases aggs, 1nat,
{
    collect(agg_arg_results(db, env, aggs))
}

pub open spec fn agg_arg(db: Database, env: Row, a: Agg) -> Result<Val, SqlError>
    decreases a,
{
    match a {
        Agg::CountStar => Ok(Val::Null),
        Agg::Count(e) => eval_expr(db, env, e),
        Agg::Sum { kind, arg } => eval_expr(db, env, arg),
        Agg::Min(e) => eval_expr(db, env, e),
        Agg::Max(e) => eval_expr(db, env, e),
        Agg::Avg { kind, arg } => eval_expr(db, env, arg),
        Agg::DistinctAgg(inner) => agg_arg(db, env, *inner),
    }
}

pub open spec fn agg_arg_results(db: Database, env: Row, aggs: Seq<Agg>) -> Seq<Result<Val, SqlError>>
    decreases aggs, 0nat,
{
    Seq::new(aggs.len(), |j: int| if 0 <= j < aggs.len() { agg_arg(db, env, aggs[j]) } else { Err(SqlError::TypeError) })
}

Query::Aggregate { aggs, input } => match type_query(schema, ctx, *input) {
    Some(tys) => type_aggs(schema, ctx + tys, aggs),
    None => None,
},

pub open spec fn type_agg(schema: Schema, env: Seq<ColTy>, a: Agg) -> Option<ColTy>
    decreases a,
{
    match a {
        Agg::CountStar => Some(nn(ScalarTy::Int8)),
        Agg::Count(e) => if type_expr(schema, env, e) is Some { Some(nn(ScalarTy::Int8)) } else { None },
        Agg::Sum { kind, arg } => match type_expr(schema, env, arg) {
            Some(t) => if !kind_accepts(kind, t.ty) { None } else {
                Some(ColTy {
                    ty: match kind {
                        NumKind::Int4 => ScalarTy::Int8,
                        NumKind::Int8 => ScalarTy::Numeric { scale: 0 },
                        NumKind::Numeric => t.ty,
                    },
                    nullable: true,
                })
            },
            None => None,
        },
        Agg::Min(e) => match type_expr(schema, env, e) {
            Some(t) => minmax_ty(t),
            None => None,
        },
        Agg::Max(e) => match type_expr(schema, env, e) {
            Some(t) => minmax_ty(t),
            None => None,
        },
        Agg::Avg { kind, arg } => match type_expr(schema, env, arg) {
            Some(t) => avg_ty(kind, t),
            None => None,
        },
        Agg::DistinctAgg(inner) => match type_agg(schema, env, *inner) {
            Some(t) => distinct_agg_ty(*inner, t),
            None => None,
        },
    }
}

pub open spec fn type_aggs(schema: Schema, env: Seq<ColTy>, aggs: Seq<Agg>) -> Option<Seq<ColTy>>
    decreases aggs,
{
    if aggs.len() == 0 {
        Some(Seq::empty())
    } else {
        match (type_aggs(schema, env, aggs.drop_last()), type_agg(schema, env, aggs.last())) {
            (Some(ts), Some(t)) => Some(ts.push(t)),
            _ => None,
        }
    }
}

Query::GroupBy { keys, aggs, input } => match eval_query(db, ctx, *input) {
    Err(err) => Err(err),
    Ok(rows) => match collect(Seq::new(rows.len(), |i: int|
        match eval_exprs(db, ctx + rows[i], keys) {
            Err(err) => Err(err),
            Ok(k) => match agg_args(db, ctx + rows[i], aggs) {
                Err(err) => Err(err),
                Ok(a) => Ok((k, a)),
            },
        })) {
        Err(err) => Err(err),
        Ok(prepared) => group_rows(
            aggs,
            prepared.map_values(|p: (Row, Row)| p.0),
            prepared.map_values(|p: (Row, Row)| p.1),
        ),
    },
},

pub open spec fn group_rows(aggs: Seq<Agg>, keys: Seq<Row>, args: Seq<Row>) -> Result<Seq<Row>, SqlError> {
    let ks = distinct_rows(keys);
    collect(Seq::new(ks.len(), |g: int|
        match agg_row(aggs, group_members(keys, args, ks[g])) {
            Ok(a) => Ok(ks[g] + a),
            Err(e) => Err(e),
        }))
}

pub open spec fn group_members(keys: Seq<Row>, args: Seq<Row>, k: Row) -> Seq<Row>
    decreases keys.len(),
{
    if keys.len() == 0 || args.len() == 0 {
        Seq::empty()
    } else {
        let init = group_members(keys.drop_last(), args.drop_last(), k);
        if row_not_distinct(keys.last(), k) { init.push(args.last()) } else { init }
    }
}

pub open spec fn group_input(db: Database, env: Row, keys: Seq<Expr>, aggs: Seq<Agg>) -> Result<(Row, Row), SqlError> {
    match eval_exprs(db, env, keys) {
        Err(err) => Err(err),
        Ok(k) => match agg_args(db, env, aggs) {
            Err(err) => Err(err),
            Ok(a) => Ok((k, a)),
        },
    }
}

Query::GroupBy { keys, aggs, input } => match type_query(schema, ctx, *input) {
    Some(tys) => match (type_exprs(schema, ctx + tys, keys), type_aggs(schema, ctx + tys, aggs)) {
        (Some(k), Some(a)) => Some(k + a),
        _ => None,
    },
    None => None,
},

pub open spec fn count_non_null(vs: Seq<Val>) -> nat
    decreases vs.len(),
{
    if vs.len() == 0 { 0 } else { count_non_null(vs.drop_last()) + if vs.last() is Null { 0nat } else { 1nat } }
}

Agg::Sum { kind, arg } => {
    if !all_of_kind(kind, vs) {
        Err(SqlError::TypeError)
    } else if count_non_null(vs) == 0 {
        Ok(Val::Null)
    } else {
        match kind {
            NumKind::Int4 => int_result(IntKind::Int8, int_sum(vs)),
            NumKind::Int8 => num_result(int_sum(vs), 0),
            NumKind::Numeric => {
                let s = num_sum(vs);
                num_result(s.0, s.1)
            },
        }
    }
},

pub open spec fn int_sum(vs: Seq<Val>) -> int
    decreases vs.len(),
{
    if vs.len() == 0 {
        0
    } else {
        int_sum(vs.drop_last()) + match vs.last() { Val::Int(x) => x, _ => 0 }
    }
}

pub open spec fn num_sum(vs: Seq<Val>) -> (int, nat)
    decreases vs.len(),
{
    if vs.len() == 0 {
        (0, 0)
    } else {
        let acc = num_sum(vs.drop_last());
        match vs.last() {
            Val::Num { coeff, scale } => (num_add_coeff(acc.0, acc.1, coeff, scale), max_nat(acc.1, scale)),
            _ => acc,
        }
    }
}

pub open spec fn all_of_kind(kind: NumKind, vs: Seq<Val>) -> bool
    decreases vs.len(),
{
    vs.len() == 0 || (all_of_kind(kind, vs.drop_last()) && match vs.last() {
        Val::Null => true,
        Val::Int(_) => !(kind is Numeric),
        Val::Num { .. } => kind is Numeric,
        _ => false,
    })
}

Agg::Sum { kind, arg } => match type_expr(schema, env, arg) {
    Some(t) => if !kind_accepts(kind, t.ty) { None } else {
        Some(ColTy {
            ty: match kind {
                NumKind::Int4 => ScalarTy::Int8,
                NumKind::Int8 => ScalarTy::Numeric { scale: 0 },
                NumKind::Numeric => t.ty,
            },
            nullable: true,
        })
    },
    None => None,
},

pub open spec fn avg_value(kind: NumKind, vs: Seq<Val>) -> Result<Val, SqlError> {
    if !all_of_kind(kind, vs) {
        Err(SqlError::TypeError)
    } else if count_non_null(vs) == 0 {
        Ok(Val::Null)
    } else {
        let s = avg_sum(kind, vs);
        // `numeric_avg` makes the sum a numeric first (`make_result`); integer sums convert exactly.
        if kind is Numeric && !num_in_range(s.0, s.1) {
            Err(SqlError::NumericValueOutOfRange)
        } else {
            num_div(s.0, s.1, count_non_null(vs) as int, 0)
        }
    }
}

pub open spec fn avg_sum(kind: NumKind, vs: Seq<Val>) -> (int, nat) {
    match kind {
        NumKind::Numeric => num_sum(vs),
        _ => (int_sum(vs), 0nat),
    }
}

Agg::Avg { kind, arg } => match type_expr(schema, env, arg) {
    Some(t) => avg_ty(kind, t),
    None => None,
},

pub open spec fn avg_ty(kind: NumKind, t: ColTy) -> Option<ColTy> {
    if kind_accepts(kind, t.ty) {
        Some(ColTy { ty: ScalarTy::Numeric { scale: 1000 }, nullable: true })
    } else {
        None
    }
}

pub open spec fn fits_avg(kind: NumKind, vs: Seq<Val>) -> bool {
    (all_of_kind(kind, vs) && count_non_null(vs) > 0) ==> {
        let s = avg_sum(kind, vs);
        num_div_fits(s.0, s.1, count_non_null(vs) as int, 0)
    }
}

pub open spec fn min_value(vs: Seq<Val>) -> Result<Val, SqlError> {
    extremum(false, vs)
}

pub open spec fn max_value(vs: Seq<Val>) -> Result<Val, SqlError> {
    extremum(true, vs)
}

pub open spec fn extremum(max: bool, vs: Seq<Val>) -> Result<Val, SqlError>
    decreases vs.len(),
{
    if vs.len() == 0 {
        Ok(Val::Null)
    } else {
        match extremum(max, vs.drop_last()) {
            Ok(acc) => extremum_step(max, acc, vs.last()),
            Err(e) => Err(e),
        }
    }
}

pub open spec fn extremum_step(max: bool, acc: Val, v: Val) -> Result<Val, SqlError> {
    if v is Null {
        Ok(acc)
    } else if v is Bool {
        Err(SqlError::TypeError)
    } else if acc is Null {
        Ok(v)
    } else {
        match compare(v, acc) {
            Some(c) => if extremum_better(max, c) { Ok(v) } else { Ok(acc) },
            None => Err(SqlError::TypeError),
        }
    }
}

pub open spec fn extremum_better(max: bool, c: int) -> bool {
    if max { c > 0 } else { c < 0 }
}

Agg::Min(e) => match type_expr(schema, env, e) {
    Some(t) => minmax_ty(t),
    None => None,
},

Agg::Max(e) => match type_expr(schema, env, e) {
    Some(t) => minmax_ty(t),
    None => None,
},

pub open spec fn minmax_ty(t: ColTy) -> Option<ColTy> {
    match t.ty {
        ScalarTy::Bool => None,
        _ => Some(ColTy { ty: t.ty, nullable: true }),
    }
}

pub open spec fn distinct_vals(vs: Seq<Val>) -> Seq<Val>
    decreases vs.len(),
{
    if vs.len() == 0 {
        Seq::empty()
    } else {
        let d = distinct_vals(vs.drop_last());
        if vs.last() is Null || has_val_not_distinct(d, vs.last()) { d } else { d.push(vs.last()) }
    }
}

pub open spec fn has_val_not_distinct(vs: Seq<Val>, v: Val) -> bool
    decreases vs.len(),
{
    vs.len() > 0 && (val_not_distinct(vs.last(), v) || has_val_not_distinct(vs.drop_last(), v))
}

Agg::DistinctAgg(inner) => match type_agg(schema, env, *inner) {
    Some(t) => distinct_agg_ty(*inner, t),
    None => None,
},

pub open spec fn distinct_agg_ty(inner: Agg, t: ColTy) -> Option<ColTy> {
    match inner {
        Agg::Count(_) | Agg::Sum { .. } | Agg::Avg { .. } => Some(t),
        _ => None,
    }
}

pub struct OrderedQuery {
    pub body: Query,
    pub keys: Seq<OrderKey>,
    pub limit: Option<nat>,
    pub offset: nat,
}

pub open spec fn denote_body(db: Database, oq: OrderedQuery) -> Result<Relation, SqlError> {
    eval_query(db, Seq::empty(), oq.body)
}

pub struct OrderKey {
    pub col: nat,
    pub desc: bool,
    pub nulls_first: bool,
}

pub open spec fn sorted_by(keys: Seq<OrderKey>, s: Seq<Row>) -> bool {
    forall|i: int, j: int| 0 <= i < j < s.len() ==> keys_cmp(keys, #[trigger] s[i], #[trigger] s[j]) <= 0
}

pub open spec fn keys_cmp(keys: Seq<OrderKey>, r1: Row, r2: Row) -> int
    decreases keys.len(),
{
    if keys.len() == 0 {
        0
    } else {
        let c = key_cmp(keys[0], r1, r2);
        if c != 0 { c } else { keys_cmp(keys.drop_first(), r1, r2) }
    }
}

pub open spec fn key_cmp(k: OrderKey, r1: Row, r2: Row) -> int {
    let a = if k.col < r1.len() { r1[k.col as int] } else { Val::Null };
    let b = if k.col < r2.len() { r2[k.col as int] } else { Val::Null };
    if a is Null && b is Null {
        0
    } else if a is Null {
        if k.nulls_first { -1 } else { 1 }
    } else if b is Null {
        if k.nulls_first { 1 } else { -1 }
    } else {
        let c = match compare(a, b) { Some(c) => c, None => 0 };
        if k.desc { -c } else { c }
    }
}

pub open spec fn slice_rows(s: Seq<Row>, offset: nat, limit: Option<nat>) -> Seq<Row> {
    let lo = if offset <= s.len() { offset as int } else { s.len() as int };
    let hi = match limit {
        Some(n) => if lo + n <= s.len() { lo + n } else { s.len() as int },
        None => s.len() as int,
    };
    s.subrange(lo, hi)
}

#[derive(Clone, Copy)]
pub enum SqlError {
    /// [22003] integer or numeric result outside its type's range.
    NumericValueOutOfRange,
    /// [22008] date/timestamp result outside PostgreSQL's range.
    DatetimeFieldOverflow,
    /// [22012] division by zero (integer and numeric division; checked before 22003).
    DivisionByZero,
    /// [21000] a scalar subquery returned more than one row.
    CardinalityViolation,
    /// [22011] negative SUBSTRING length.
    SubstringError,
    /// [22025] LIKE: an escape string longer than one character ("invalid escape string", `like_escape`), or
    /// the matcher reaching an escape at the end of the pattern ("LIKE pattern must not end with escape
    /// character"). PostgreSQL 18 uses 22025 for both (`spec::fns::like`).
    InvalidEscapeSequence,
    /// [22019] Reserved in the encoding; no supported construct raises it (PostgreSQL's LIKE uses 22025).
    InvalidEscapeCharacter,
    /// Ill-typed operands (not a SQL outcome; see above).
    TypeError,
}

pub open spec fn collect<T>(rs: Seq<Result<T, SqlError>>) -> Result<Seq<T>, SqlError>
    decreases rs.len(),
{
    if rs.len() == 0 {
        Ok(Seq::empty())
    } else {
        match collect(rs.drop_last()) {
            Err(e) => Err(e),
            Ok(vs) => match rs.last() {
                Err(e) => Err(e),
                Ok(v) => Ok(vs.push(v)),
            },
        }
    }
}

pub open spec fn ordered_ok(db: Database, oq: OrderedQuery, out: Result<Relation, SqlError>) -> bool {
    match denote_body(db, oq) {
        Err(e) => out == Err::<Relation, SqlError>(e),
        Ok(rows) => exists|p: Seq<Row>| #![trigger sorted_by(oq.keys, p)]
            p.to_multiset() == rows.to_multiset() && sorted_by(oq.keys, p)
                && out == Ok::<Relation, SqlError>(slice_rows(p, oq.offset, oq.limit)),
    }
}

pub open spec fn denote_top(db: Database, oq: OrderedQuery) -> Result<Relation, SqlError> {
    match denote_body(db, oq) {
        Err(e) => Err(e),
        Ok(rows) => Ok(slice_rows(sort_rows(oq.keys, rows), oq.offset, oq.limit)),
    }
}

pub open spec fn sort_rows(keys: Seq<OrderKey>, s: Seq<Row>) -> Seq<Row>
    decreases s.len(),
{
    if s.len() == 0 { s } else { insert_sorted(keys, sort_rows(keys, s.drop_last()), s.last()) }
}

pub open spec fn insert_sorted(keys: Seq<OrderKey>, s: Seq<Row>, r: Row) -> Seq<Row>
    decreases s.len(),
{
    if s.len() == 0 {
        seq![r]
    } else if keys_cmp(keys, s.last(), r) <= 0 {
        s.push(r)
    } else {
        insert_sorted(keys, s.drop_last(), r).push(s.last())
    }
}

